head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > P > useMonthSelect]<br/>Calendar 컴포넌트의 월 SelectBox 활성화 여부를 설정합니다.",
    "validation" : [
        "미설정(기본값 true) 시 월 SelectBox 가 활성화되어 사용자가 드롭다운에서 월을 직접 선택할 수 있습니다.",
        "true 설정 시 월 SelectBox 가 활성화되어 사용자가 드롭다운에서 월을 직접 선택할 수 있습니다.",
        "true 설정 시 사용자가 월을 변경하면 onmonthselect 이벤트가 발생합니다.",
        "true 설정 시 사용자가 월을 변경하면 onviewchange 이벤트가 발생합니다.",
        "false 설정 시 월 SelectBox 가 읽기 전용으로 설정되어 사용자가 드롭다운에서 월을 선택할 수 없습니다.",
        "false 설정 시에도 gotoMonth() 등의 메소드를 통한 월 이동은 동작합니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        useMonthSelect : con_useMonthSelect.getText()
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onmonthselect", "onviewchange"]);

    $c.gcm.createLabel('label="useMonthSelect 설정 후 월 SelectBox 활성/비활성 및 gotoMonth() 동작 확인"', '', 'label1');
    await $c.gcm.createBasicCalendar(cList, eList);
}



// [속성/DOM 정보 조회] 버튼
// validation:
//  - 월 SelectBox 의 readOnly 상태 확인 (false 설정 시 readOnly=true)
scwin.btn_getInfo_onclick = function (e) {
    // 월 SelectBox 자식 컴포넌트 조회
    let monthSb = target1.getChild(target1.id + "_selectbox_month");

    // validation: 월 SelectBox 의 readOnly 상태 (true 면 활성화, false 면 읽기 전용)
    //  - 엔진: readOnly: !this.options.useMonthSelect → useMonthSelect=false 시 readOnly=true
    let monthReadOnly = monthSb ? monthSb.options.readOnly : '(없음)';
    wf_body_bottom.getObj("scwin").setReturnValue("[월 SelectBox readOnly] " + monthReadOnly
        + " (useMonthSelect=false 일 때 readOnly=true → 드롭다운 선택 불가)");

    // validation: 현재 선택된 월 (gotoMonth 호출 전후 비교 기준)
    wf_body_bottom.getObj("scwin").setReturnValue("[현재 선택 값] target1.getValue() = '" + target1.getValue() + "'");
}



// [gotoMonth(3) 호출] 버튼
// validation: false 설정 시에도 gotoMonth() 등의 메소드를 통한 월 이동은 동작
scwin.btn_gotoMonth_onclick = function (e) {
    let beforeVal = target1.getValue();
    target1.gotoMonth(3);
    let afterVal = target1.getValue();

    wf_body_bottom.getObj("scwin").setReturnValue("[gotoMonth(3) 호출] 호출 전 값='" + beforeVal
        + "' / 호출 후 값='" + afterVal + "' (useMonthSelect=false 여도 메소드 호출에 의한 월 이동은 동작)");
}



// onmonthselect 이벤트 핸들러
// validation:
//  - true 설정 시 사용자가 월 SelectBox 에서 월 변경 → onmonthselect 이벤트 발생
//  - info 객체 (oldValue, newValue) 가 핸들러에 전달됨
scwin.target1_onmonthselect = function (e, info) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onmonthselect 이벤트 발생] 사용자 월 변경 시 호출됨");
    if (info) {
        wf_body_bottom.getObj("scwin").setReturnValue("[onmonthselect info.oldValue] " + info.oldValue);
        wf_body_bottom.getObj("scwin").setReturnValue("[onmonthselect info.newValue] " + info.newValue);
    }
};



// onviewchange 이벤트 핸들러
// validation: true 설정 시 사용자가 월 SelectBox 에서 월 변경 → onviewchange 이벤트 발생
scwin.target1_onviewchange = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onviewchange 이벤트 발생] 사용자 액션으로 값이 변경되어 onviewchange 핸들러 호출됨");
};
